INSERT INTO `classes` VALUES (3,2,3,3,'TOEIC 600+ Foundation - 01','T600-EVE-2026','Lớp học 12 tuần dành cho học viên đi học hoặc đi làm, tập trung củng cố ngữ pháp, từ vựng và chiến thuật Listening - Reading để hướng tới TOEIC 600+.','2026-09-28','2026-12-20',30,'OPEN','2026-09-25 00:25:01','2026-09-25 00:26:11'),(4,2,3,3,'TOEIC 600+ Foundation - 02','T600-WKD-2026','Lớp học cuối tuần theo lộ trình TOEIC 600+ Roadmap 12 Weeks, kết hợp bài giảng nền tảng, luyện đề theo từng Part và theo dõi tiến độ hằng tuần.','2026-10-03','2026-12-20',25,'OPEN','2026-09-25 00:25:01','2026-09-25 00:26:25'),(1000,1000,3,3,'TOEIC 450+ Starter – Lớp tối 2-4-6','S450-EVE-2610','Lớp buổi tối dành cho người đi làm, học 3 buổi mỗi tuần.','2026-10-12','2026-11-22',30,'OPEN','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1001,1000,3,3,'TOEIC 450+ Starter – Khóa hè','S450-SUM-2607','Lớp cấp tốc mùa hè đã kết thúc.','2026-07-06','2026-08-16',25,'COMPLETED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1002,1001,3,3,'TOEIC 650+ Intermediate – Lớp sáng cuối tuần','I650-WKD-2609','Học sáng thứ Bảy và Chủ nhật, phù hợp sinh viên năm cuối.','2026-09-26','2026-11-22',35,'OPEN','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1003,1001,3,3,'TOEIC 650+ Intermediate – Lớp online','I650-ONL-2611','Lớp học trực tuyến qua Zoom, khai giảng tháng 11.','2026-11-02','2026-12-27',40,'OPEN','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1004,1002,3,3,'Listening Intensive – Lớp tối 3-5','LIS-EVE-2610','Luyện nghe – nói chuyên sâu vào tối thứ Ba và thứ Năm.','2026-10-06','2026-11-10',20,'OPEN','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1005,1002,3,3,'Listening Intensive – Lớp đã đóng','LIS-CLS-2608','Lớp tháng 8 đã đóng do chuyển lịch sang lớp tối.','2026-08-03','2026-09-07',20,'COMPLETED','2026-10-05 09:00:00','2026-10-05 09:00:00');
