INSERT INTO `course_weeks` VALUES (1,2,1,'Grammar Foundations I','Present Simple, Present Continuous và phần thực hành bổ sung.','PUBLISHED','2026-09-28 00:02:37','2026-09-28 00:02:37'),(2,2,2,'Grammar Foundations II','Past Simple, Present Perfect, Future Forms và Parts of Speech.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(3,2,3,'Listening Basics','TOEIC Listening Part 1–2: Photographs và Question–Response.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(4,2,4,'Listening Conversations & Talks','TOEIC Listening Part 3–4: Conversations và Short Talks.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(5,2,5,'Listening for Details','Luyện nghe số, ngày tháng và các chi tiết quan trọng.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(6,2,6,'Reading Foundations','TOEIC Reading Part 5–6: Incomplete Sentences và Text Completion.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(7,2,7,'Reading Part 7','Đọc hiểu Emails, Memos, Advertisements và Notices.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(8,2,8,'Reading Strategy','Chiến lược đọc và quản lý thời gian trong bài TOEIC.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(9,2,9,'Vocabulary: Office & Meetings','Từ vựng văn phòng, hành chính, cuộc họp và hội nghị.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(10,2,10,'Vocabulary: Travel & Marketing','Từ vựng du lịch, vận tải, marketing và bán hàng.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(11,2,11,'Vocabulary: Finance & Purchasing','Từ vựng tài chính, hóa đơn, thanh toán và mua hàng.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(12,2,12,'Review & Practice','Tuần dự phòng cho bài ôn tập, luyện tập và đánh giá tổng hợp.','DRAFT','2026-09-28 00:02:37','2026-09-28 00:02:37'),(1000,1000,1,'Làm quen với bài thi TOEIC','Cấu trúc đề, cách tính điểm và từ vựng văn phòng cơ bản.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1001,1000,2,'Thì hiện tại','Hiện tại đơn, hiện tại tiếp diễn và mô tả tranh Part 1.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1002,1000,3,'Quá khứ và tương lai','Kể lại công việc đã làm và nói về kế hoạch sắp tới.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1003,1000,4,'Hỏi và đáp','Chiến thuật Part 2 và giới từ chỉ thời gian, nơi chốn.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1004,1000,5,'Từ loại và đọc hiểu ngắn','Tính từ, trạng từ và đọc thông báo ngắn Part 7.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1005,1000,6,'Ôn tập và luyện đề','Tổng hợp ngữ pháp nền tảng, luyện Part 5 và lập kế hoạch tự học.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1006,1001,1,'Chiến lược Part 5','Từ loại, mệnh đề quan hệ và từ vựng marketing.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1007,1001,2,'Câu bị động và hội thoại','Bị động trong thông báo công ty và chiến thuật Part 3.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1008,1001,3,'Liên từ và điền đoạn văn','Liên từ, giới từ dễ nhầm, Part 6 và e-mail thương mại.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1009,1001,4,'So sánh và bài nói ngắn','Cấu trúc so sánh, Part 4 và đọc quảng cáo.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1010,1001,5,'Danh động từ và câu điều kiện','V-ing hay to V, câu điều kiện và từ vựng nhân sự.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1011,1001,6,'Đọc hiểu đa văn bản','Đang biên soạn: đoạn kép, suy luận và từ vựng hợp đồng.','DRAFT','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1012,1001,7,'Nghe nâng cao','Đang biên soạn: Part 3 có biểu đồ, ý định người nói và thì hoàn thành.','DRAFT','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1013,1001,8,'Tổng ôn','Đang biên soạn: ôn Part 5–6, quản lý thời gian và đề tổng hợp.','DRAFT','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1014,1002,1,'Part 1 – Mô tả tranh','Tranh có người, tranh đồ vật và hiện tại tiếp diễn.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1015,1002,2,'Part 2 – Hỏi đáp','Câu hỏi Wh-, câu đề nghị và từ phát âm dễ nhầm.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1016,1002,3,'Part 3 – Hội thoại','Hội thoại hai người, ba người và từ vựng hội họp.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1017,1002,4,'Part 4 – Bài nói ngắn','Thông báo, tin nhắn thoại, quảng cáo và đọc to đoạn văn.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1018,1002,5,'Speaking và ôn luyện','Mô tả tranh, trả lời câu hỏi và nêu ý kiến.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1019,1002,6,'Tuần luyện đề (đang cập nhật)','Giáo viên sẽ bổ sung đề luyện nghe tổng hợp cho tuần này.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1020,1003,1,'Ngữ pháp nâng cao','Đảo ngữ và mệnh đề rút gọn.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1021,1003,2,'Đọc hiểu nâng cao','Đoạn ba văn bản và từ vựng học thuật kinh doanh.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1022,1003,3,'Nghe nâng cao','Part 3–4 tốc độ cao và tổng ôn 800+.','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00');
