INSERT INTO `courses` VALUES (2,3,'TOEIC 600+ Foundation','toeic-600-foundation-demo','A practical 12-week TOEIC foundation course covering essential grammar, workplace vocabulary, listening strategies, and reading skills for learners targeting 600 points or higher.','INTERMEDIATE',600,1890000,'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?auto=format&fit=crop&w=1200&q=80','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24','2026-09-25 00:09:24'),(1000,3,'TOEIC 450+ Starter','toeic-450-starter-seed','Khóa học khởi động 6 tuần dành cho người mới bắt đầu luyện TOEIC. Bạn sẽ làm quen cấu trúc bài thi, nắm chắc các thì cơ bản, từ loại, giới từ và khoảng 150 từ vựng công sở thông dụng, đồng thời luyện Part 1, Part 2 và Part 5 với chiến thuật đơn giản, dễ áp dụng.','BEGINNER',450,1290000,'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1200&q=80','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1001,3,'TOEIC 650+ Intermediate','toeic-650-intermediate-seed','Khóa học 8 tuần cho người đã có nền tảng (khoảng 400–500 điểm) muốn đạt 650+. Trọng tâm là chiến thuật Part 3–4, Part 6–7 và các chủ điểm ngữ pháp hay ra: từ loại, bị động, mệnh đề quan hệ, liên từ, so sánh, câu điều kiện. Ba tuần cuối đang được biên soạn.','INTERMEDIATE',650,1890000,'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1002,3,'TOEIC Listening Intensive','toeic-listening-intensive-seed','Khóa luyện nghe và nói chuyên sâu trong 5 tuần: từ Part 1 mô tả tranh đến Part 4 bài nói ngắn, kết hợp các dạng bài TOEIC Speaking (đọc đoạn văn, mô tả tranh, trả lời câu hỏi, nêu ý kiến). Mỗi bài có hoạt động nghe và bài nói để luyện phản xạ.','INTERMEDIATE',600,990000,'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1200&q=80','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1003,3,'TOEIC 800+ Advanced','toeic-800-advanced-seed','Khóa nâng cao 3 tuần cho học viên đã đạt 700+: ngữ pháp trang trọng (đảo ngữ, mệnh đề rút gọn), đọc hiểu ba văn bản, từ vựng hợp đồng và nghe tốc độ cao. Khóa đang được hoàn thiện nên chưa hiển thị cho học viên.','ADVANCED',800,2490000,'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1200&q=80','DRAFT',NULL,'2026-10-05 09:00:00','2026-10-05 09:00:00');
