/*!40000 ALTER TABLE `grammar_topics` DISABLE KEYS */;
INSERT INTO `grammar_topics` VALUES (1000,3,1000,1001,'Danh từ đếm được, không đếm được và đại từ','Danh từ đếm được có dạng số nhiều (report → reports) và đi với a/an, many, a few. Danh từ không đếm được (equipment, information, furniture, advice) không có -s và đi với much, a little, some.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1001,3,1001,1002,'Thì hiện tại đơn','Dùng cho thói quen, lịch trình, sự thật và quy định của công ty.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1002,3,1001,1003,'Thì hiện tại tiếp diễn (và bị động tiếp diễn trong Part 1)','Dùng cho hành động đang diễn ra lúc nói hoặc kế hoạch đã sắp xếp trong tương lai gần.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1003,3,1001,1004,'So sánh hơn và so sánh nhất','So sánh hơn: adj-er / more + adj + than. So sánh nhất: the + adj-est / the most + adj.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1004,3,1002,1005,'Thì quá khứ đơn','Dùng cho hành động đã xảy ra và kết thúc tại thời điểm xác định trong quá khứ.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1005,3,1002,1006,'Tương lai: will, be going to và hiện tại cho tương lai','will + V: quyết định tức thời, dự đoán, lời hứa, thông báo chính thức.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1006,3,1003,1007,'Đại từ phản thân và đại từ bất định','Đại từ phản thân (myself, yourself, themselves): khi chủ ngữ và tân ngữ là một; by + oneself = tự mình.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1007,3,1003,1009,'Giới từ chỉ thời gian và nơi chốn','Thời gian: at + giờ (at 9 A.M.), on + ngày/thứ (on May 5, on Monday), in + tháng/năm/buổi (in June, in the morning), by + hạn chót (by Friday), until + mốc kéo dài (until 5 P.M.), within + khoảng (within two days).','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1008,3,1004,1010,'Tính từ và trạng từ','Tính từ bổ nghĩa cho danh từ (a careful review) hoặc đứng sau động từ nối be, seem, become, remain, look (The plan seems reasonable).','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1009,3,1004,1011,'Liên từ và giới từ dễ nhầm','Liên từ + mệnh đề (S + V): although, because, while, unless, once, since.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1010,3,1005,1012,'Sự hòa hợp chủ ngữ – động từ','Động từ chia theo chủ ngữ chính, bỏ qua cụm giới từ chen giữa: The list of products IS ready.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1011,3,1005,1013,'Từ loại và vị trí từ trong câu','Nhận diện vị trí trống để chọn từ loại:','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1012,3,1006,1015,'Từ loại và vị trí từ trong câu','Nhận diện vị trí trống để chọn từ loại:','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1013,3,1006,1016,'Đại từ quan hệ','who: thay cho người (chủ ngữ); whom: người (tân ngữ); which: vật; that: người/vật (không dùng sau dấu phẩy và giới từ); whose + N: sở hữu; where: nơi chốn; when: thời gian.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1014,3,1007,1018,'Câu bị động','Dùng khi muốn nhấn mạnh đối tượng chịu tác động hoặc không cần nêu người thực hiện.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1015,3,1007,1019,'Tương lai: will, be going to và hiện tại cho tương lai','will + V: quyết định tức thời, dự đoán, lời hứa, thông báo chính thức.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1016,3,1008,1021,'Liên từ và giới từ dễ nhầm','Liên từ + mệnh đề (S + V): although, because, while, unless, once, since.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1017,3,1008,1023,'Đại từ phản thân và đại từ bất định','Đại từ phản thân (myself, yourself, themselves): khi chủ ngữ và tân ngữ là một; by + oneself = tự mình.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1018,3,1009,1024,'So sánh hơn và so sánh nhất','So sánh hơn: adj-er / more + adj + than. So sánh nhất: the + adj-est / the most + adj.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1019,3,1009,1025,'Thì quá khứ đơn','Dùng cho hành động đã xảy ra và kết thúc tại thời điểm xác định trong quá khứ.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1020,3,1009,1026,'Tính từ và trạng từ','Tính từ bổ nghĩa cho danh từ (a careful review) hoặc đứng sau động từ nối be, seem, become, remain, look (The plan seems reasonable).','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1021,3,1010,1027,'Danh động từ (V-ing) và động từ nguyên mẫu (to V)','Theo sau bởi V-ing: avoid, consider, recommend, suggest, finish, enjoy, look forward to, be committed to.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1022,3,1010,1028,'Câu điều kiện','Loại 1 (có thể xảy ra): If + hiện tại đơn, will/can + V.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1023,3,1011,1030,'Động từ khiếm khuyết','must/have to: bắt buộc; should/ought to: nên; may/might: có thể (khả năng); can/could: có thể (năng lực, xin phép).','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1024,3,1011,1031,'Sự hòa hợp chủ ngữ – động từ','Động từ chia theo chủ ngữ chính, bỏ qua cụm giới từ chen giữa: The list of products IS ready.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1025,3,1011,1032,'Giới từ chỉ thời gian và nơi chốn','Thời gian: at + giờ (at 9 A.M.), on + ngày/thứ (on May 5, on Monday), in + tháng/năm/buổi (in June, in the morning), by + hạn chót (by Friday), until + mốc kéo dài (until 5 P.M.), within + khoảng (within two days).','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1026,3,1012,1034,'Thì hiện tại đơn','Dùng cho thói quen, lịch trình, sự thật và quy định của công ty.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1027,3,1012,1035,'Thì hiện tại hoàn thành','Dùng cho hành động bắt đầu trong quá khứ kéo dài đến hiện tại, hoặc vừa hoàn tất và có kết quả ở hiện tại.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1028,3,1014,1040,'Câu bị động','Dùng khi muốn nhấn mạnh đối tượng chịu tác động hoặc không cần nêu người thực hiện.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1029,3,1014,1041,'Thì hiện tại tiếp diễn (và bị động tiếp diễn trong Part 1)','Dùng cho hành động đang diễn ra lúc nói hoặc kế hoạch đã sắp xếp trong tương lai gần.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1030,3,1015,1042,'Thì quá khứ đơn','Dùng cho hành động đã xảy ra và kết thúc tại thời điểm xác định trong quá khứ.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1031,3,1016,1045,'Tương lai: will, be going to và hiện tại cho tương lai','will + V: quyết định tức thời, dự đoán, lời hứa, thông báo chính thức.','BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1032,3,1017,1048,'Động từ khiếm khuyết','must/have to: bắt buộc; should/ought to: nên; may/might: có thể (khả năng); can/could: có thể (năng lực, xin phép).','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1033,3,1017,1049,'So sánh hơn và so sánh nhất','So sánh hơn: adj-er / more + adj + than. So sánh nhất: the + adj-est / the most + adj.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1034,3,1018,1053,'Câu điều kiện','Loại 1 (có thể xảy ra): If + hiện tại đơn, will/can + V.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1035,3,1020,1054,'Đảo ngữ trong văn bản trang trọng','Đảo trợ động từ lên trước chủ ngữ sau các trạng từ phủ định/giới hạn đứng đầu câu: Never, Rarely, Seldom, Not only, Only after, No sooner ... than, Hardly ... when.','ADVANCED','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1036,3,1020,1055,'Mệnh đề rút gọn và phân từ','Rút gọn mệnh đề quan hệ: chủ động → V-ing (employees working late), bị động → V3 (products made in Vietnam).','ADVANCED','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1037,3,1021,1056,'Đại từ quan hệ','who: thay cho người (chủ ngữ); whom: người (tân ngữ); which: vật; that: người/vật (không dùng sau dấu phẩy và giới từ); whose + N: sở hữu; where: nơi chốn; when: thời gian.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1038,3,1022,1058,'Danh động từ (V-ing) và động từ nguyên mẫu (to V)','Theo sau bởi V-ing: avoid, consider, recommend, suggest, finish, enjoy, look forward to, be committed to.','INTERMEDIATE','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2000,3,1,4,'Present Simple: thói quen và quy định nơi công sở','Thì hiện tại đơn diễn tả thói quen, lịch làm việc cố định, quy định của công ty và sự thật hiển nhiên.','BEGINNER','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2001,3,1,5,'Present Continuous: dự án đang triển khai','Thì hiện tại tiếp diễn diễn tả hành động đang xảy ra lúc nói, dự án đang tiến hành trong giai đoạn hiện tại và kế hoạch đã sắp xếp cho tương lai gần..','BEGINNER','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2002,3,2,6,'Past Simple và Present Perfect: báo cáo kết quả','Quá khứ đơn nói về việc đã xong tại thời điểm xác định trong quá khứ.','BEGINNER','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2003,3,2,7,'Future Forms: will, be going to và lịch trình','Tiếng Anh có nhiều cách nói về tương lai: will cho quyết định tức thời và thông báo, be going to cho kế hoạch đã định, hiện tại đơn cho lịch trình cố định, hiện tại tiếp diễn cho kế hoạch đã sắp xếp..','BEGINNER','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2004,3,2,8,'Parts of Speech: chọn đúng từ loại','Câu hỏi từ loại chiếm khoảng 1/3 Part 5.','INTERMEDIATE','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2005,3,6,14,'Part 5: giới từ và liên từ hay gặp','Nhiều câu Part 5 hỏi giới từ (despite, due to, during) hoặc liên từ (although, because, unless).','INTERMEDIATE','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2006,3,6,15,'Part 6: từ nối và tham chiếu trong đoạn văn','Part 6 kiểm tra mạch văn: từ nối thể hiện quan hệ giữa hai câu, đại từ (it, they, this) phải khớp với danh từ đã nhắc, và thì động từ phải khớp với thời điểm của sự việc..','INTERMEDIATE','PUBLISHED','2026-10-08 21:00:00','2026-10-08 21:00:00'),(2007,3,3,9,'Part 1: Photographs',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2008,3,3,10,'Part 2: Question–Response',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2009,3,4,11,'Part 3: Short Conversations',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2010,3,4,12,'Part 4: Short Talks',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2011,3,5,13,'Listening for Numbers, Dates, and Details',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2012,3,7,16,'Part 7: Emails and Memos',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2013,3,7,17,'Part 7: Advertisements and Notices',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2014,3,8,18,'Reading Strategies and Time Management',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2015,3,9,19,'Office and Administration Vocabulary',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2016,3,9,20,'Meetings and Conferences Vocabulary',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2017,3,10,21,'Travel and Transportation Vocabulary',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2018,3,10,22,'Marketing and Sales Vocabulary',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2019,3,11,23,'Finance and Purchasing Vocabulary',NULL,'BEGINNER','PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2020,3,1000,1000,'Tổng quan bài thi TOEIC Listening & Reading',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2021,3,1003,1008,'Câu hỏi Yes/No, câu hỏi đuôi và lựa chọn',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2022,3,1005,1014,'Kế hoạch tự học sau khóa',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2023,3,1006,1017,'Từ vựng: Marketing & quảng cáo',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2024,3,1007,1020,'Từ vựng: Sản xuất & nhà máy',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2025,3,1008,1022,'Part 6: Điền vào đoạn văn',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2026,3,1010,1029,'Từ vựng: Nhân sự & tuyển dụng',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2027,3,1012,1033,'Part 3 có biểu đồ, bảng biểu',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2028,3,1013,1036,'Ôn tập Part 5–6',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2029,3,1013,1037,'Chiến lược quản lý thời gian',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2030,3,1013,1038,'Đề luyện tổng hợp',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2031,3,1014,1039,'Tranh có người',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2032,3,1015,1043,'Câu đề nghị và câu hỏi gián tiếp',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2033,3,1015,1044,'Từ phát âm dễ nhầm',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2034,3,1016,1046,'Hội thoại ba người',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2035,3,1016,1047,'Từ vựng: Hội nghị & sự kiện',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2036,3,1017,1050,'Speaking: Đọc to đoạn văn',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2037,3,1018,1051,'Speaking: Mô tả tranh',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2038,3,1018,1052,'Speaking: Trả lời câu hỏi',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2039,3,1021,1057,'Từ vựng: Hợp đồng & pháp lý',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(2040,3,1022,1059,'Tổng ôn 800+',NULL,'BEGINNER','PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00');
