INSERT INTO `lessons` VALUES (4,1,3,'Present Simple in the Workplace','Use the present simple to describe routines, policies, schedules, and permanent business facts.\n\nIdentify present-simple signals; choose correct subject-verb agreement; write accurate workplace routine sentences.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(5,1,3,'Present Continuous and Current Projects','Describe temporary activities and actions happening around the present time.\n\nRecognize present-continuous time markers; form be plus verb-ing; distinguish routines from temporary projects.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(6,2,3,'Past Simple and Present Perfect','Choose between completed past events and experiences or results connected to the present.\n\nUse past-time markers correctly; form the present perfect; avoid combining present perfect with finished times.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(7,2,3,'Future Forms and Schedules','Express predictions, plans, arrangements, and scheduled future events.\n\nDifferentiate will, be going to, present continuous, and timetable present simple; identify appropriate future context.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(8,2,3,'Parts of Speech and Sentence Completion','Select nouns, verbs, adjectives, and adverbs by analyzing sentence position.\n\nRecognize common suffixes; use modifiers accurately; solve TOEIC Part 5 word-form questions efficiently.',3,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(9,3,3,'Part 1: Photographs','Identify people, objects, actions, and locations in TOEIC photograph descriptions.\n\nFocus on visible evidence; distinguish active and passive descriptions; avoid sound-alike distractors.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(10,3,3,'Part 2: Question–Response','Respond appropriately to information questions, yes/no questions, requests, and suggestions.\n\nIdentify the question type from the first word; recognize indirect responses; avoid repeated-word traps.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(11,4,3,'Part 3: Short Conversations','Follow workplace conversations and identify purpose, details, problems, and next actions.\n\nPreview questions; track speakers and setting; infer what a speaker will probably do next.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(12,4,3,'Part 4: Short Talks','Understand announcements, recorded messages, advertisements, and brief presentations.\n\nRecognize talk type; capture sequence and purpose; connect verbal information with likely actions.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(13,5,3,'Listening for Numbers, Dates, and Details','Accurately hear times, prices, dates, quantities, addresses, and reference numbers.\n\nDistinguish easily confused numbers; record units; confirm details through context.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(14,6,3,'Part 5: Incomplete Sentences','Solve single-sentence grammar and vocabulary questions efficiently.\n\nClassify each blank; use local grammar clues; manage time with a twenty-second decision process.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(15,6,3,'Part 6: Text Completion','Complete emails, notices, articles, and letters using grammar and discourse clues.\n\nUse surrounding sentences; identify logical connectors; choose sentences that maintain topic flow.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(16,7,3,'Part 7: Emails and Memos','Read workplace emails and memos for purpose, detail, implication, and next action.\n\nLocate sender, recipient, and purpose; scan for requested actions; recognize paraphrases.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(17,7,3,'Part 7: Advertisements and Notices','Interpret promotions, public notices, job advertisements, and service announcements.\n\nFind eligibility, price, location, and deadline information; recognize conditions and exceptions.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(18,8,3,'Reading Strategies and Time Management','Complete the reading section accurately within the official time limit.\n\nAllocate time across Parts 5–7; skim and scan strategically; use evidence to eliminate distractors.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(19,9,3,'Office and Administration Vocabulary','Learn essential words used in offices, personnel notices, facilities, and daily administration.\n\nUnderstand common office nouns and verbs; use collocations such as file a report and arrange an appointment.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(20,9,3,'Meetings and Conferences Vocabulary','Build vocabulary for agendas, presentations, negotiations, and conference arrangements.\n\nRecognize meeting-related expressions; understand formal announcements; select appropriate business collocations.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(21,10,3,'Travel and Transportation Vocabulary','Master language used in itineraries, airports, hotels, commuting, and business travel.\n\nRead travel notices; understand itinerary changes; use transport vocabulary in realistic situations.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(22,10,3,'Marketing and Sales Vocabulary','Understand common language used in promotions, customer research, product launches, and sales reports.\n\nInterpret marketing messages; use sales collocations; distinguish customers, clients, consumers, and prospects.',2,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(23,11,3,'Finance and Purchasing Vocabulary','Learn vocabulary for budgets, invoices, payments, purchasing, and financial performance.\n\nUnderstand invoices and purchase notices; use finance terms accurately; identify common payment expressions.',1,45,'PUBLISHED','2026-09-25 00:09:24','2026-09-25 00:09:24'),(1000,1000,3,'Tổng quan bài thi TOEIC Listening & Reading','Bài thi TOEIC Listening & Reading gồm 200 câu trắc nghiệm trong khoảng 2 giờ, thang điểm 10–990.',1,30,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1001,1000,3,'Danh từ và đại từ trong môi trường văn phòng','Chủ điểm ngữ pháp: Danh từ đếm được, không đếm được và đại từ. Từ vựng chủ đề văn phòng dùng trong bài thi TOEIC.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1002,1001,3,'Hiện tại đơn: thói quen nơi công sở','Chủ điểm ngữ pháp: Thì hiện tại đơn. Từ vựng chủ đề văn phòng dùng trong bài thi TOEIC.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1003,1001,3,'Hiện tại tiếp diễn và mô tả tranh Part 1','Chủ điểm ngữ pháp: Thì hiện tại tiếp diễn (và bị động tiếp diễn trong Part 1). Part 1 yêu cầu chọn câu mô tả đúng nhất một bức tranh.',2,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1004,1001,3,'Từ vựng: Đi lại và công tác','Chủ điểm ngữ pháp: So sánh hơn và so sánh nhất. Từ vựng chủ đề du lịch & công tác dùng trong bài thi TOEIC.',3,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1005,1002,3,'Quá khứ đơn: báo cáo công việc','Chủ điểm ngữ pháp: Thì quá khứ đơn. Từ vựng chủ đề nhân sự & tuyển dụng dùng trong bài thi TOEIC.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1006,1002,3,'Tương lai: will và be going to','Chủ điểm ngữ pháp: Tương lai: will, be going to và hiện tại cho tương lai. Từ vựng chủ đề hội nghị & sự kiện dùng trong bài thi TOEIC.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1007,1003,3,'Part 2: Câu hỏi Wh-','Chủ điểm ngữ pháp: Đại từ phản thân và đại từ bất định. Part 2 có 25 câu hỏi – đáp, mỗi câu 3 phương án chỉ nghe một lần.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1008,1003,3,'Câu hỏi Yes/No, câu hỏi đuôi và lựa chọn','Câu hỏi Yes/No, câu hỏi đuôi và câu hỏi lựa chọn chiếm gần nửa Part 2.',2,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1009,1003,3,'Giới từ chỉ thời gian và nơi chốn','Chủ điểm ngữ pháp: Giới từ chỉ thời gian và nơi chốn. Từ vựng chủ đề mua sắm & bán lẻ dùng trong bài thi TOEIC.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1010,1004,3,'Tính từ và trạng từ','Chủ điểm ngữ pháp: Tính từ và trạng từ. Từ vựng chủ đề mua sắm & bán lẻ dùng trong bài thi TOEIC.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1011,1004,3,'Đọc thông báo ngắn (Part 7)','Chủ điểm ngữ pháp: Liên từ và giới từ dễ nhầm. Part 7 là phần đọc hiểu dài nhất.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1012,1005,3,'Ôn tập: hòa hợp chủ ngữ – động từ','Chủ điểm ngữ pháp: Sự hòa hợp chủ ngữ – động từ. Part 5 gồm 30 câu điền từ, kiểm tra ngữ pháp và từ vựng.',1,55,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1013,1005,3,'Luyện đề mini Part 5','Chủ điểm ngữ pháp: Từ loại và vị trí từ trong câu. Part 5 gồm 30 câu điền từ, kiểm tra ngữ pháp và từ vựng.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1014,1005,3,'Kế hoạch tự học sau khóa','Kết thúc khóa học là lúc lập kế hoạch tự học để giữ nhịp.',3,30,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1015,1006,3,'Từ loại và vị trí từ trong câu','Chủ điểm ngữ pháp: Từ loại và vị trí từ trong câu. Part 5 gồm 30 câu điền từ, kiểm tra ngữ pháp và từ vựng.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1016,1006,3,'Đại từ quan hệ','Chủ điểm ngữ pháp: Đại từ quan hệ. Từ vựng chủ đề nhân sự & tuyển dụng dùng trong bài thi TOEIC.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1017,1006,3,'Từ vựng Marketing & quảng cáo','Từ vựng chủ đề marketing & quảng cáo dùng trong bài thi TOEIC.',3,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1018,1007,3,'Câu bị động trong thông báo công ty','Chủ điểm ngữ pháp: Câu bị động. Từ vựng chủ đề sản xuất & nhà máy dùng trong bài thi TOEIC.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1019,1007,3,'Part 3: Hội thoại công sở','Chủ điểm ngữ pháp: Tương lai: will, be going to và hiện tại cho tương lai. Part 3 gồm các đoạn hội thoại công sở, mỗi đoạn có 3 câu hỏi in sẵn trên đề.',2,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1020,1007,3,'Từ vựng Sản xuất & nhà máy','Từ vựng chủ đề sản xuất & nhà máy dùng trong bài thi TOEIC.',3,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1021,1008,3,'Liên từ và giới từ dễ nhầm','Chủ điểm ngữ pháp: Liên từ và giới từ dễ nhầm. Từ vựng chủ đề tài chính & kế toán dùng trong bài thi TOEIC.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1022,1008,3,'Part 6: Điền vào đoạn văn','Part 6 gồm 4 đoạn văn, mỗi đoạn 4 chỗ trống, trong đó có một câu chọn cả câu phù hợp.',2,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1023,1008,3,'Đọc e-mail và thư thương mại','Chủ điểm ngữ pháp: Đại từ phản thân và đại từ bất định. E-mail và thư thương mại là dạng văn bản phổ biến nhất trong Part 7.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1024,1009,3,'So sánh hơn và so sánh nhất','Chủ điểm ngữ pháp: So sánh hơn và so sánh nhất. Từ vựng chủ đề bất động sản & cơ sở vật chất dùng trong bài thi TOEIC.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1025,1009,3,'Part 4: Thông báo và tin nhắn thoại','Chủ điểm ngữ pháp: Thì quá khứ đơn. Part 4 là bài nói của một người: thông báo, tin nhắn thoại, hướng dẫn, quảng cáo.',2,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1026,1009,3,'Đọc quảng cáo và tin tuyển dụng (Part 7)','Chủ điểm ngữ pháp: Tính từ và trạng từ. Quảng cáo và thông báo tuyển dụng có bố cục rõ ràng với nhiều chi tiết số liệu.',3,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1027,1010,3,'V-ing hay to V?','Chủ điểm ngữ pháp: Danh động từ (V-ing) và động từ nguyên mẫu (to V). Từ vựng chủ đề nhân sự & tuyển dụng dùng trong bài thi TOEIC.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1028,1010,3,'Câu điều kiện loại 1, 2, 3','Chủ điểm ngữ pháp: Câu điều kiện. Từ vựng chủ đề tài chính & kế toán dùng trong bài thi TOEIC.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1029,1010,3,'Từ vựng Nhân sự & tuyển dụng','Từ vựng chủ đề nhân sự & tuyển dụng dùng trong bài thi TOEIC.',3,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1030,1011,3,'Part 7: Đoạn kép','Chủ điểm ngữ pháp: Động từ khiếm khuyết. Đoạn kép gồm hai văn bản liên quan (thư và lịch, quảng cáo và đơn hàng).',1,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1031,1011,3,'Câu hỏi suy luận','Chủ điểm ngữ pháp: Sự hòa hợp chủ ngữ – động từ. Câu hỏi suy luận (most likely, suggested, implied) không có đáp án viết sẵn trong bài.',2,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1032,1011,3,'Từ vựng Hợp đồng & pháp lý','Chủ điểm ngữ pháp: Giới từ chỉ thời gian và nơi chốn. Từ vựng chủ đề hợp đồng & pháp lý dùng trong bài thi TOEIC.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1033,1012,3,'Part 3 có biểu đồ, bảng biểu','Một số câu Part 3–4 kèm bảng biểu, lịch, bản đồ.',1,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1034,1012,3,'Câu hỏi ý định người nói','Chủ điểm ngữ pháp: Thì hiện tại đơn. Câu hỏi ý định người nói (What does the speaker mean when she says…?) kiểm tra khả năng hiểu ngữ cảnh..',2,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1035,1012,3,'Thì hiện tại hoàn thành','Chủ điểm ngữ pháp: Thì hiện tại hoàn thành. Từ vựng chủ đề công nghệ & thiết bị dùng trong bài thi TOEIC.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1036,1013,3,'Ôn tập Part 5–6','Part 5 gồm 30 câu điền từ, kiểm tra ngữ pháp và từ vựng.',1,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1037,1013,3,'Chiến lược quản lý thời gian','Quản lý thời gian quyết định bạn có làm hết phần Đọc hay không.',2,30,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1038,1013,3,'Đề luyện tổng hợp','Làm đề tổng hợp giúp bạn đánh giá năng lực thật và rèn sức bền tập trung trong 2 giờ..',3,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1039,1014,3,'Tranh có người','Tranh có một hoặc nhiều người chiếm phần lớn đề Part 1.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1040,1014,3,'Tranh đồ vật và khung cảnh','Chủ điểm ngữ pháp: Câu bị động. Tranh không có người hoặc người chỉ là chi tiết phụ thường mô tả vị trí đồ vật và trạng thái của cảnh.',2,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1041,1014,3,'Hiện tại tiếp diễn và bị động tiếp diễn','Chủ điểm ngữ pháp: Thì hiện tại tiếp diễn (và bị động tiếp diễn trong Part 1). Part 1 yêu cầu chọn câu mô tả đúng nhất một bức tranh.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1042,1015,3,'Câu hỏi Wh- và từ để hỏi','Chủ điểm ngữ pháp: Thì quá khứ đơn. Part 2 có 25 câu hỏi – đáp, mỗi câu 3 phương án chỉ nghe một lần.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1043,1015,3,'Câu đề nghị và câu hỏi gián tiếp','Câu đề nghị, yêu cầu và câu hỏi gián tiếp đòi hỏi bạn hiểu chức năng của câu thay vì từ để hỏi..',2,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1044,1015,3,'Từ phát âm dễ nhầm','Nhiều đáp án sai trong phần Nghe dùng từ phát âm gần giống từ trong câu hỏi.',3,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1045,1016,3,'Hội thoại hai người','Chủ điểm ngữ pháp: Tương lai: will, be going to và hiện tại cho tương lai. Part 3 gồm các đoạn hội thoại công sở, mỗi đoạn có 3 câu hỏi in sẵn trên đề.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1046,1016,3,'Hội thoại ba người','Hội thoại có ba người khó hơn vì phải theo dõi ai nói gì.',2,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1047,1016,3,'Từ vựng Hội nghị & sự kiện','Từ vựng chủ đề hội nghị & sự kiện dùng trong bài thi TOEIC.',3,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1048,1017,3,'Thông báo và tin nhắn thoại','Chủ điểm ngữ pháp: Động từ khiếm khuyết. Part 4 là bài nói của một người: thông báo, tin nhắn thoại, hướng dẫn, quảng cáo.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1049,1017,3,'Quảng cáo và bản tin','Chủ điểm ngữ pháp: So sánh hơn và so sánh nhất. Quảng cáo và bản tin trong Part 4 nói nhanh, nhiều chi tiết.',2,55,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1050,1017,3,'Speaking: Đọc to đoạn văn','Phần Read a Text Aloud trong TOEIC Speaking chấm phát âm, ngữ điệu và trọng âm.',3,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1051,1018,3,'Speaking: Mô tả tranh','Describe a Picture: bạn có 45 giây chuẩn bị và 30 giây để mô tả bức tranh.',1,35,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1052,1018,3,'Speaking: Trả lời câu hỏi','Respond to Questions: ba câu hỏi về một chủ đề quen thuộc, thời gian trả lời 15–30 giây.',2,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1053,1018,3,'Speaking: Nêu ý kiến','Chủ điểm ngữ pháp: Câu điều kiện. Express an Opinion là phần cuối Speaking: 45 giây chuẩn bị, 60 giây trình bày quan điểm có lý do và ví dụ..',3,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1054,1020,3,'Đảo ngữ trong văn bản trang trọng','Chủ điểm ngữ pháp: Đảo ngữ trong văn bản trang trọng. Từ vựng chủ đề tài chính & kế toán dùng trong bài thi TOEIC.',1,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1055,1020,3,'Mệnh đề rút gọn và phân từ','Chủ điểm ngữ pháp: Mệnh đề rút gọn và phân từ. Từ vựng chủ đề hợp đồng & pháp lý dùng trong bài thi TOEIC.',2,45,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1056,1021,3,'Part 7: Ba văn bản','Chủ điểm ngữ pháp: Đại từ quan hệ. Đoạn ba văn bản là thử thách lớn nhất của Part 7, đòi hỏi tốc độ đọc và khả năng liên kết thông tin..',1,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1057,1021,3,'Từ vựng hợp đồng nâng cao','Từ vựng chủ đề hợp đồng & pháp lý dùng trong bài thi TOEIC.',2,40,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1058,1022,3,'Part 3–4 tốc độ cao','Chủ điểm ngữ pháp: Danh động từ (V-ing) và động từ nguyên mẫu (to V). Ở mức 800+, bài nói Part 4 có tốc độ nhanh và nhiều thông tin gây nhiễu.',1,50,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00'),(1059,1022,3,'Tổng ôn 800+','Quản lý thời gian quyết định bạn có làm hết phần Đọc hay không.',2,30,'PUBLISHED','2026-10-05 09:00:00','2026-10-05 09:00:00');
