  `question_id` bigint unsigned NOT NULL,
  `selected_option_id` bigint unsigned DEFAULT NULL,
  `is_correct` tinyint(1) NOT NULL DEFAULT '0',
  `score_awarded` decimal(6,2) NOT NULL DEFAULT '0.00',
  `option_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_listening_answer` (`attempt_id`,`question_id`),
  KEY `fk_listening_answer_question` (`question_id`),
  KEY `fk_listening_answer_option` (`selected_option_id`),
  KEY `idx_listening_answer_current_option` (`option_id`),
  CONSTRAINT `fk_listening_answer_attempt` FOREIGN KEY (`attempt_id`) REFERENCES `listening_attempts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_listening_answer_current_option` FOREIGN KEY (`option_id`) REFERENCES `listening_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_listening_answer_option` FOREIGN KEY (`selected_option_id`) REFERENCES `listening_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_listening_answer_question` FOREIGN KEY (`question_id`) REFERENCES `listening_questions` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
