--
-- Table structure for table `listening_questions`
--

DROP TABLE IF EXISTS `listening_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listening_questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `question_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `score` decimal(6,2) NOT NULL DEFAULT '1.00',
  `sort_order` int unsigned NOT NULL DEFAULT '1',
  `listening_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_listening_question_activity` (`listening_id`),
  CONSTRAINT `fk_listening_question_activity` FOREIGN KEY (`listening_id`) REFERENCES `listening_activities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2026 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

