INSERT INTO `listening_questions` VALUES (1000,'Why is the woman calling?','Người phụ nữ gọi để đổi lịch hẹn từ thứ Năm sang thứ Sáu.',1.00,1,1000),(1001,'Why is Dr. Lim unavailable on Thursday?','\"Dr. Lim has to attend a conference that day.\"',1.00,2,1000),(1002,'When will the man come?','\"Friday at the same time\" tức 10 giờ sáng thứ Sáu.',1.00,3,1000),(1003,'What problem are the speakers discussing?','Máy photocopy bị kẹt giấy.',1.00,1,1001),(1004,'What will the woman do?','\"I\'ll call the technician.\"',1.00,2,1001),(1005,'What does the man need the copies for?','\"…for the two o\'clock training.\"',1.00,3,1001),(1006,'Where is the announcement being made?','Thông báo cho hành khách chuyến bay, cửa ra máy bay.',1.00,1,1002),(1007,'What has changed?','Cửa đổi từ 8 sang 14.',1.00,2,1002),(1008,'What time will boarding begin?','\"Boarding will begin at 11:20.\"',1.00,3,1002),(1009,'What kind of business does the speaker work for?','\"Green Leaf Office Supplies\".',1.00,1,1003),(1010,'What will be delivered tomorrow?','Giấy có sẵn và giao ngày mai.',1.00,2,1003),(1011,'Why should the listener call back?','\"If that\'s a problem, please call me back.\"',1.00,3,1003),(1012,'What does the woman want to do?','Cô ấy muốn đặt phòng họp lớn.',1.00,1,1004),(1013,'How many people will attend?','\"About twenty.\"',1.00,2,1004),(1014,'What will the man send?','\"…send you a confirmation e-mail.\"',1.00,3,1004),(1015,'Who most likely are the listeners?','\"Welcome… on today\'s tour\" → khách tham quan.',1.00,1,1005),(1016,'What are the listeners asked to do?','\"Please wear the protective glasses.\"',1.00,2,1005),(1017,'What is offered at the end of the tour?','Giảm 10% tại phòng trưng bày.',1.00,3,1005),(1018,'Why is the man calling?','Đơn hàng lẽ ra đến hôm qua.',1.00,1,1006),(1019,'What caused the delay?','\"The truck was delayed by a storm.\"',1.00,2,1006),(1020,'What does the man ask for?','\"…make sure the driver calls me before delivery.\"',1.00,3,1006),(1021,'What is the main topic of the broadcast?','Bản tin giao thông.',1.00,1,1007),(1022,'What does the speaker recommend?','\"take Dien Bien Phu Street instead\".',1.00,2,1007),(1023,'When is the next update?','\"another update at eight o\'clock\".',1.00,3,1007),(1024,'What are the speakers planning?','Tiệc chia tay ông Quang nghỉ hưu.',1.00,1,1008),(1025,'Why does the woman reject the restaurant as a venue?','\"…but it\'s small.\"',1.00,2,1008),(1026,'What will the man do?','\"I\'ll ask everyone to sign a card.\"',1.00,3,1008),(1027,'Where is the announcement heard?','\"Attention, shoppers… City Mart.\"',1.00,1,1009),(1028,'What are listeners asked to do?','\"bring your final purchases to the checkout\".',1.00,2,1009),(1029,'What is on sale tomorrow?','Giảm đến 40% đồ gia dụng nhà bếp.',1.00,3,1009),(1030,'What is the purpose of the call?','Mời phỏng vấn vòng hai.',1.00,1,1010),(1031,'Who will the woman meet?','\"You\'ll meet our sales director.\"',1.00,2,1010),(1032,'What should the woman bring?','\"Just a copy of your portfolio.\"',1.00,3,1010),(1033,'What is the talk mainly about?','Hệ thống báo cáo chi phí mới.',1.00,1,1011),(1034,'What advantage of the system is mentioned?','\"submit receipts directly from your phone\".',1.00,2,1011),(1035,'What should listeners do by Wednesday?','\"Please sign up on the intranet by Wednesday.\"',1.00,3,1011),(1036,'Where does the conversation take place?','Nhận phòng khách sạn.',1.00,1,1012),(1037,'How long will the man stay?','\"three nights in a deluxe room\".',1.00,2,1012),(1038,'How often does the shuttle leave?','\"every half hour\".',1.00,3,1012),(1039,'What is the speaker calling about?','Về hợp đồng đã gửi.',1.00,1,1013),(1040,'What does the speaker want to change?','Điều 7 về điều khoản thanh toán.',1.00,2,1013),(1041,'When is the speaker available?','\"I\'m free after nine\" sáng mai.',1.00,3,1013),(1042,'What are the speakers discussing?','So sánh hai nhà cung cấp cà phê.',1.00,1,1014),(1043,'Why does the man prefer Mountain Roast?','Giao hàng hai lần mỗi tuần.',1.00,2,1014),(1044,'What will the woman ask Mountain Roast?','\"ask if they can lower the price\".',1.00,3,1014),(1045,'Who is the speaker addressing?','Lời chào khách tham quan bảo tàng.',1.00,1,1015),(1046,'Where is photography NOT allowed?','Ngoại trừ triển lãm đặc biệt tầng 3.',1.00,2,1015),(1047,'What should listeners do at the end?','Trả thiết bị tại quầy lễ tân.',1.00,3,1015),(1048,'What new policy are the speakers discussing?','Làm việc tại nhà hai ngày mỗi tuần.',1.00,1,1016),(1049,'When does the policy begin?','\"starting in July\".',1.00,2,1016),(1050,'Why must employees be in the office on Mondays?','\"…on Mondays for the team meeting\".',1.00,3,1016),(1051,'Why will the library close?','Đóng cửa để cải tạo.',1.00,1,1017),(1052,'How can books be returned during the closure?','Hộp trả sách ngoài cửa chính.',1.00,2,1017),(1053,'What will NOT be new after the library reopens?','Bài không nhắc đến quán cà phê.',1.00,3,1017),(1054,'What problem do the speakers have?','Báo giá vượt ngân sách khoảng 2.000 đô.',1.00,1,1018),(1055,'What does the woman suggest?','Cắt quảng cáo in, tập trung mạng xã hội.',1.00,2,1018),(1056,'What will happen on Thursday?','Trình kế hoạch với giám đốc thứ Năm.',1.00,3,1018),(1057,'Where does the talk most likely take place?','Ca làm, khu bốc dỡ hàng → nhà kho.',1.00,1,1019),(1058,'What caused the injuries?','Hộp để trên lối đi.',1.00,2,1019),(1059,'What will happen on Friday?','Thanh tra an toàn đến thứ Sáu.',1.00,3,1019),(1060,'What is the problem with the coffee maker?','Máy ngừng hoạt động.',1.00,1,1020),(1061,'What does the man ask for?','\"Do you have the receipt?\"',1.00,2,1020),(1062,'What will the woman receive?','\"A replacement is fine.\"',1.00,3,1020),(1063,'What caused the increase in revenue?','\"mainly thanks to strong online sales\".',1.00,1,1021),(1064,'What problem does the speaker mention?','Chi phí vận chuyển tăng.',1.00,2,1021),(1065,'What will Linh talk about?','\"…explain our marketing plans\".',1.00,3,1021),(1066,'What event are the speakers preparing for?','\"The trade fair is in three weeks.\"',1.00,1,1022),(1067,'What are they waiting for?','\"waiting for the printed banners\".',1.00,2,1022),(1068,'What will they do next Monday?','\"set up a practice display in the lobby next Monday\".',1.00,3,1022),(1069,'What problem is the message about?','\"If your laptop will not turn on\".',1.00,1,1023),(1070,'How long should the listener hold the power button?','\"hold the power button for ten seconds\".',1.00,2,1023),(1071,'What can listeners do on the Web site?','\"book a free repair appointment\".',1.00,3,1023),(2000,'What is the man\'s situation?','\"I just started in the sales department.\"',1.00,1,2000),(2001,'When does the team meet?','\"the team meets every Monday at nine\".',1.00,2,2000),(2002,'What do salespeople do every week?','\"each salesperson sends a sales report by Friday afternoon\".',1.00,3,2000),(2003,'What happens on the last Friday of the month?','\"the office closes early on the last Friday of the month\".',1.00,4,2000),(2004,'Ảnh 1 cho thấy một người đàn ông ngồi trước máy tính xách tay. Câu mô tả đúng là:','Hành động chính trong ảnh là gõ bàn phím laptop.',1.00,1,2001),(2005,'Ảnh 2: nhiều thùng carton xếp sát tường, không có người. Câu đúng là:','Không có người → loại câu \"are being opened\"; mô tả trạng thái: stacked against a wall.',1.00,2,2001),(2006,'Ảnh 3: hai người phụ nữ cùng xem một tờ giấy trên bàn. Câu đúng là:','Hai người đang cùng xem tài liệu.',1.00,3,2001),(2007,'Ảnh 4: hội trường trống, ghế xếp thành hàng ngay ngắn. Câu đúng là:','Không có người; ghế đã được xếp thành hàng → bị động hoàn thành.',1.00,4,2001),(2008,'\"Where is the supply closet?\" – Câu trả lời phù hợp nhất:','Câu hỏi Where → trả lời nơi chốn. \"closed\" là bẫy âm giống \"closet\".',1.00,1,2002),(2009,'\"When will the new printer arrive?\" – Câu trả lời phù hợp nhất:','When → thời gian.',1.00,2,2002),(2010,'\"Who\'s in charge of the training program?\" – Câu trả lời phù hợp nhất:','Who → người. \"train\", \"charge\" là bẫy lặp từ.',1.00,3,2002),(2011,'\"Why don\'t we order lunch for the team?\" – Câu trả lời phù hợp nhất:','\"Why don\'t we…?\" là lời đề nghị, không hỏi lý do.',1.00,4,2002),(2012,'\"Would you mind sending me the file again?\" – Câu trả lời phù hợp nhất:','Đồng ý với \"Would you mind…?\" bằng \"Not at all\".',1.00,5,2002),(2013,'What are the speakers discussing?','Đặt bàn mới cho nhóm thiết kế.',1.00,1,2003),(2014,'What problem does the man mention?','\"raised its prices by fifteen percent\".',1.00,2,2003),(2015,'What does the woman suggest?','\"ask Bright Office for a quotation\".',1.00,3,2003),(2016,'Why does the man want delivery before the end of the month?','\"…when the new designers start\".',1.00,4,2003),(2017,'Who most likely is the listener?','\"I\'m calling about your talk on Saturday\".',1.00,1,2004),(2018,'Why was the session moved?','\"more than four hundred people have registered\".',1.00,2,2004),(2019,'What time will the session start?','\"now starts at 10:30\".',1.00,3,2004),(2020,'What will happen at 10 o\'clock?','\"A technician will be there at 10 to help you set up the projector\".',1.00,4,2004),(2021,'How many tickets does the man want?','\"two round-trip tickets\".',1.00,1,2005),(2022,'When will the man return?','\"returning on the 18th\" (tháng 6).',1.00,2,2005),(2023,'What time does the flight leave?','\"a 7:45 morning flight\".',1.00,3,2005),(2024,'What is the booking code?','\"Your booking code is PQ-5172.\"',1.00,4,2005),(2025,'How long does the man have to pay?','\"within 24 hours\".',1.00,5,2005);
