INSERT INTO `questions` VALUES (1,3,4,'PART_5','EASY','DEMO600:GRA-01:Q01','Ms. Rivera _____ the weekly sales report every Friday afternoon.',NULL,NULL,NULL,'Every Friday signals a routine, and the singular subject Ms. Rivera requires the third-person form prepares.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(2,3,4,'PART_5','MEDIUM','DEMO600:GRA-01:Q02','The main conference room _____ at the moment, so the interview will be held in Room 204.',NULL,NULL,NULL,'At the moment requires the present continuous, and the room receives the action, so the passive form is being cleaned is correct.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(3,3,4,'PART_5','EASY','DEMO600:GRA-01:Q03','Representatives from both companies _____ the final agreement yesterday.',NULL,NULL,NULL,'Yesterday is a finished past-time marker, so the past simple signed is required.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(4,3,4,'PART_5','MEDIUM','DEMO600:GRA-01:Q04','The company _____ the name of its new regional director at tomorrow\'s staff meeting.',NULL,NULL,NULL,'The future time tomorrow and the planned announcement make will announce the best choice.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(5,3,4,'PART_5','EASY','DEMO600:GRA-01:Q05','The revised reimbursement policy will take effect _____ January 1.',NULL,NULL,NULL,'Use the preposition on before a specific date.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(6,3,4,'PART_5','EASY','DEMO600:GRA-01:Q06','Please forward the signed invoice _____ the accounting department before noon.',NULL,NULL,NULL,'The verb forward uses the pattern forward something to someone or a department.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-09-25 00:09:24'),(7,3,4,'PART_5','MEDIUM','DEMO600:GRA-01:Q07','Several flights were delayed _____ severe weather near the airport.',NULL,NULL,NULL,'Because of must be followed by a noun phrase, severe weather.',1.00,'ACTIVE','2026-09-25 00:09:24','2026-