CREATE TABLE course_tests (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  course_id BIGINT UNSIGNED NOT NULL,
  created_by_teacher_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(220) NOT NULL,
  description TEXT NULL,
  status ENUM('DRAFT','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'DRAFT',
  current_version_no INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_course_test (course_id),
  KEY idx_course_test_teacher (created_by_teacher_id),
  CONSTRAINT fk_course_test_course FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_course_test_teacher FOREIGN KEY (created_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_versions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  test_id BIGINT UNSIGNED NOT NULL,
  version_no INT UNSIGNED NOT NULL,
  status ENUM('DRAFT','PUBLISHED','SUPERSEDED') NOT NULL DEFAULT 'DRAFT',
  time_limit_minutes INT UNSIGNED NOT NULL,
  pass_percent DECIMAL(5,2) NOT NULL,
  total_points DECIMAL(9,2) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  published_at DATETIME NULL,
  UNIQUE KEY uq_test_version (test_id,version_no),
  CONSTRAINT fk_test_version_test FOREIGN KEY (test_id) REFERENCES course_tests(id) ON DELETE RESTRICT,
  CONSTRAINT chk_test_time CHECK (time_limit_minutes BETWEEN 1 AND 360),
  CONSTRAINT chk_test_pass CHECK (pass_percent BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ngân hàng đề thi: Nghe/Đọc/Nói dùng riêng cho Test cuối khóa, không thuộc khóa học/tuần/bài.
CREATE TABLE test_bank_listening_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  created_by_teacher_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(200) NOT NULL,
  instruction TEXT NULL,
  audio_url VARCHAR(1000) NULL,
  status ENUM('ACTIVE','HIDDEN') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_tb_listening_teacher (created_by_teacher_id,status),
  CONSTRAINT fk_tb_listening_teacher FOREIGN KEY (created_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_listening_questions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  item_id BIGINT UNSIGNED NOT NULL,
  question_text TEXT NOT NULL,
  sort_order INT UNSIGNED NOT NULL DEFAULT 1,
  KEY idx_tb_listening_question_item (item_id),
  CONSTRAINT fk_tb_listening_question_item FOREIGN KEY (item_id) REFERENCES test_bank_listening_items(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_listening_options (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  question_id BIGINT UNSIGNED NOT NULL,
  option_text TEXT NOT NULL,
  is_correct TINYINT(1) NOT NULL DEFAULT 0,
  sort_order INT UNSIGNED NOT NULL DEFAULT 1,
  KEY idx_tb_listening_option_question (question_id),
  CONSTRAINT fk_tb_listening_option_question FOREIGN KEY (question_id) REFERENCES test_bank_listening_questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_reading_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  created_by_teacher_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(200) NOT NULL,
  instruction TEXT NULL,
  passage LONGTEXT NULL,
  passage_format ENUM('PLAIN','MARKDOWN') NOT NULL DEFAULT 'MARKDOWN',
  toeic_part ENUM('PART_6','PART_7','GENERAL') NOT NULL DEFAULT 'PART_7',
  passage_type ENUM('SINGLE','DOUBLE','TRIPLE') NOT NULL DEFAULT 'SINGLE',
  status ENUM('ACTIVE','HIDDEN') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_tb_reading_teacher (created_by_teacher_id,status),
  CONSTRAINT fk_tb_reading_teacher FOREIGN KEY (created_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_reading_attachments (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  item_id BIGINT UNSIGNED NOT NULL,
  kind ENUM('FILE','LINK') NOT NULL DEFAULT 'FILE',
  title VARCHAR(200) NOT NULL,
  url VARCHAR(1000) NOT NULL,
  file_name VARCHAR(255) NULL,
  mime_type VARCHAR(100) NULL,
  size_bytes BIGINT UNSIGNED NULL,
  sort_order INT UNSIGNED NOT NULL,
  UNIQUE KEY uq_tb_reading_attachment_order (item_id,sort_order),
  CONSTRAINT fk_tb_reading_attachment_item FOREIGN KEY (item_id) REFERENCES test_bank_reading_items(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_reading_questions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  item_id BIGINT UNSIGNED NOT NULL,
  question_text TEXT NOT NULL,
  explanation TEXT NULL,
  evidence TEXT NULL,
  sort_order INT UNSIGNED NOT NULL DEFAULT 1,
  KEY idx_tb_reading_question_item (item_id),
  CONSTRAINT fk_tb_reading_question_item FOREIGN KEY (item_id) REFERENCES test_bank_reading_items(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_reading_options (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  question_id BIGINT UNSIGNED NOT NULL,
  option_text TEXT NOT NULL,
  is_correct TINYINT(1) NOT NULL DEFAULT 0,
  sort_order INT UNSIGNED NOT NULL DEFAULT 1,
  KEY idx_tb_reading_option_question (question_id),
  CONSTRAINT fk_tb_reading_option_question FOREIGN KEY (question_id) REFERENCES test_bank_reading_questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_speaking_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  created_by_teacher_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(200) NOT NULL,
  instruction TEXT NOT NULL,
  prompt_text TEXT NULL,
  status ENUM('ACTIVE','HIDDEN') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_tb_speaking_teacher (created_by_teacher_id,status),
  CONSTRAINT fk_tb_speaking_teacher FOREIGN KEY (created_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bộ đề: nhóm nhiều câu hỏi của ngân hàng, chọn cả bộ vào một phần Test.
CREATE TABLE test_bank_question_sets (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  created_by_teacher_id BIGINT UNSIGNED NOT NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NULL,
  status ENUM('ACTIVE','HIDDEN') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_tb_question_set_teacher (created_by_teacher_id,status),
  CONSTRAINT fk_tb_question_set_teacher FOREIGN KEY (created_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_bank_question_set_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  set_id BIGINT UNSIGNED NOT NULL,
  question_id BIGINT UNSIGNED NOT NULL,
  sort_order INT UNSIGNED NOT NULL,
  UNIQUE KEY uq_tb_question_set_question (set_id,question_id),
  UNIQUE KEY uq_tb_question_set_order (set_id,sort_order),
  KEY idx_tb_question_set_item_question (question_id),
  CONSTRAINT fk_tb_question_set_item_set FOREIGN KEY (set_id) REFERENCES test_bank_question_sets(id) ON DELETE CASCADE,
  CONSTRAINT fk_tb_question_set_item_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_sections (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  version_id BIGINT UNSIGNED NOT NULL,
  sort_order INT UNSIGNED NOT NULL,
  source_type ENUM('QUESTION','QUESTION_SET','LISTENING','READING','SPEAKING') NOT NULL,
  source_question_id BIGINT UNSIGNED NULL,
  source_listening_id BIGINT UNSIGNED NULL,
  source_reading_id BIGINT UNSIGNED NULL,
  source_speaking_id BIGINT UNSIGNED NULL,
  source_test_listening_id BIGINT UNSIGNED NULL,
  source_test_reading_id BIGINT UNSIGNED NULL,
  source_test_speaking_id BIGINT UNSIGNED NULL,
  source_test_question_set_id BIGINT UNSIGNED NULL,
  title VARCHAR(255) NOT NULL,
  duration_minutes INT UNSIGNED NOT NULL,
  question_count INT UNSIGNED NOT NULL,
  max_points DECIMAL(9,2) NOT NULL,
  snapshot_json JSON NULL,
  UNIQUE KEY uq_test_section_order (version_id,sort_order),
  KEY idx_test_section_question (source_question_id),
  KEY idx_test_section_listening (source_listening_id),
  KEY idx_test_section_reading (source_reading_id),
  KEY idx_test_section_speaking (source_speaking_id),
  KEY idx_test_section_tb_listening (source_test_listening_id),
  KEY idx_test_section_tb_reading (source_test_reading_id),
  KEY idx_test_section_tb_speaking (source_test_speaking_id),
  KEY idx_test_section_tb_question_set (source_test_question_set_id),
  CONSTRAINT fk_test_section_version FOREIGN KEY (version_id) REFERENCES test_versions(id) ON DELETE CASCADE,
  CONSTRAINT fk_test_section_question FOREIGN KEY (source_question_id) REFERENCES questions(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_listening FOREIGN KEY (source_listening_id) REFERENCES listening_activities(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_reading FOREIGN KEY (source_reading_id) REFERENCES reading_activities(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_speaking FOREIGN KEY (source_speaking_id) REFERENCES speaking_activities(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_tb_listening FOREIGN KEY (source_test_listening_id) REFERENCES test_bank_listening_items(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_tb_reading FOREIGN KEY (source_test_reading_id) REFERENCES test_bank_reading_items(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_tb_speaking FOREIGN KEY (source_test_speaking_id) REFERENCES test_bank_speaking_items(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_section_tb_question_set FOREIGN KEY (source_test_question_set_id) REFERENCES test_bank_question_sets(id) ON DELETE RESTRICT,
  CONSTRAINT chk_test_section_source CHECK (
    (source_question_id IS NOT NULL) + (source_listening_id IS NOT NULL) +
    (source_reading_id IS NOT NULL) + (source_speaking_id IS NOT NULL) +
    (source_test_listening_id IS NOT NULL) + (source_test_reading_id IS NOT NULL) +
    (source_test_speaking_id IS NOT NULL) + (source_test_question_set_id IS NOT NULL) = 1
  ),
  CONSTRAINT chk_test_section_points CHECK (max_points > 0),
  CONSTRAINT chk_test_section_duration CHECK (duration_minutes > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_attempts (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  test_id BIGINT UNSIGNED NOT NULL,
  version_id BIGINT UNSIGNED NOT NULL,
  student_id BIGINT UNSIGNED NOT NULL,
  status ENUM('IN_PROGRESS','PENDING_GRADING','GRADED') NOT NULL DEFAULT 'IN_PROGRESS',
  started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at DATETIME NOT NULL,
  submitted_at DATETIME NULL,
  auto_submitted TINYINT(1) NOT NULL DEFAULT 0,
  earned_points DECIMAL(9,2) NULL,
  total_points DECIMAL(9,2) NOT NULL,
  passed TINYINT(1) NULL,
  UNIQUE KEY uq_test_student_version (test_id,student_id,version_id),
  KEY idx_test_attempt_version (version_id),
  KEY idx_test_attempt_student_date (student_id,started_at),
  CONSTRAINT fk_test_attempt_test FOREIGN KEY (test_id) REFERENCES course_tests(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_attempt_version FOREIGN KEY (version_id) REFERENCES test_versions(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_attempt_student FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_answers (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  attempt_id BIGINT UNSIGNED NOT NULL,
  section_id BIGINT UNSIGNED NOT NULL,
  question_key VARCHAR(40) NOT NULL,
  selected_option_id BIGINT UNSIGNED NULL,
  is_correct TINYINT(1) NULL,
  saved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_test_answer (attempt_id,section_id,question_key),
  KEY idx_test_answer_section (section_id),
  CONSTRAINT fk_test_answer_attempt FOREIGN KEY (attempt_id) REFERENCES test_attempts(id) ON DELETE CASCADE,
  CONSTRAINT fk_test_answer_section FOREIGN KEY (section_id) REFERENCES test_sections(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_recordings (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  attempt_id BIGINT UNSIGNED NOT NULL,
  section_id BIGINT UNSIGNED NOT NULL,
  storage_url VARCHAR(1000) NOT NULL,
  mime_type VARCHAR(100) NOT NULL,
  size_bytes BIGINT UNSIGNED NOT NULL,
  saved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_test_recording (attempt_id,section_id),
  KEY idx_test_recording_section (section_id),
  CONSTRAINT fk_test_recording_attempt FOREIGN KEY (attempt_id) REFERENCES test_attempts(id) ON DELETE CASCADE,
  CONSTRAINT fk_test_recording_section FOREIGN KEY (section_id) REFERENCES test_sections(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE test_section_scores (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  attempt_id BIGINT UNSIGNED NOT NULL,
  section_id BIGINT UNSIGNED NOT NULL,
  earned_points DECIMAL(9,2) NOT NULL,
  max_points DECIMAL(9,2) NOT NULL,
  graded_by_teacher_id BIGINT UNSIGNED NULL,
  graded_at DATETIME NULL,
  feedback TEXT NULL,
  UNIQUE KEY uq_test_section_score (attempt_id,section_id),
  KEY idx_test_section_score_section (section_id),
  CONSTRAINT fk_test_score_attempt FOREIGN KEY (attempt_id) REFERENCES test_attempts(id) ON DELETE CASCADE,
  CONSTRAINT fk_test_score_section FOREIGN KEY (section_id) REFERENCES test_sections(id) ON DELETE RESTRICT,
  CONSTRAINT fk_test_score_teacher FOREIGN KEY (graded_by_teacher_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT chk_test_score_range CHECK (earned_points >= 0 AND earned_points <= max_points)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

