INSERT INTO test_bank_reading_items(created_by_teacher_id,title,instruction,passage,passage_format,toeic_part,passage_type,status) VALUES (3,'Test: E-mail — Flight Rebooking Confirmation','Read the e-mail and answer the questions.','**To:** Daniel Okoye
**From:** Pacific Air Customer Service
**Subject:** Your rebooked flight

Dear Mr. Okoye,

Thank you for contacting us about your canceled flight to Seoul. We have rebooked you on flight PA 217, which departs on October 9 at 8:20 a.m. and arrives at 3:05 p.m. local time.

Because the new flight leaves two hours earlier than your original booking, please arrive at the airport no later than 6:00 a.m. Your seat assignment, 14C, has been kept the same as before. A meal voucher worth fifteen dollars will be sent to your phone within 24 hours.

We apologize for the inconvenience.

Sincerely,
Lena Park
Pacific Air Customer Service','MARKDOWN','PART_7','SINGLE','ACTIVE');
