INSERT INTO test_bank_reading_items(created_by_teacher_id,title,instruction,passage,passage_format,toeic_part,passage_type,status) VALUES (3,'Test: Job Advertisement and Cover Letter','Read the two documents and answer the questions.','## Job Advertisement

**Position:** Customer Support Coordinator, Northwind Appliances
**Location:** Denver, Colorado
**Requirements:** Two years of experience in customer service, fluent Spanish, and strong communication skills.
**Application deadline:** June 15. Applicants should send a résumé and a cover letter to hiring@northwind.example.

## Cover Letter

Dear Hiring Manager,

I am writing to apply for the Customer Support Coordinator position advertised on your Web site. For the past three years, I have worked as a support agent at Brightline Electronics, where I handled more than fifty customer inquiries a day. I am fluent in both English and Spanish and recently completed a certificate course in conflict resolution.

I would welcome the opportunity to discuss my qualifications in an interview. I am available at any time after June 20.

Sincerely,
Carla Mendes','MARKDOWN','PART_7','DOUBLE','ACTIVE');
SET @i=LAST_INSERT_ID();
