INSERT INTO test_bank_speaking_items(created_by_teacher_id,title,instruction,prompt_text,status) VALUES (3,'Test: Read aloud — Pharmacy opening hours notice','Read the text below aloud. You have 45 seconds to speak clearly and at a natural pace.','Welcome to Maple Street Pharmacy. Our store is open from eight a.m. to nine p.m. on weekdays, and from nine a.m. to six p.m. on weekends. Prescriptions that are submitted before noon can be picked up the same day. For your convenience, we also offer free home delivery for orders over thirty dollars.','ACTIVE');
INSERT INTO test_bank_speaking_items(created_by_teacher_id,title,instruction,prompt_text,status) VALUES (3,'Test: Describe a picture — A busy train platform','Describe the picture in as much detail as you can. Imagine a photograph of a train platform during the morning rush hour.','Talk about: the people waiting on the platform, what some of them are carrying, the train arriving, the electronic sign above the platform, and what the atmosphere seems to be like.','ACTIVE');
INSERT INTO test_bank_speaking_items(created_by_teacher_id,title,instruction,prompt_text,status) VALUES (3,'Test: Respond to questions — Public transportation','Answer the three questions about public transportation. You have 15 seconds to answer each question.','1) How do you usually travel to work or school? 2) What is the biggest advantage of using public transportation in your city? 3) What would you change to make public transportation better?','ACTIVE');
INSERT INTO test_bank_speaking_items(created_by_teacher_id,title,instruction,prompt_text,status) VALUES (3,'Test: Express an opinion — Working from home','Some companies allow employees to work from home. Do you think this is a good idea? Give reasons and examples. You have 60 seconds to speak.','Consider: flexibility, communication with colleagues, productivity, and work-life balance.','ACTIVE');
INSERT INTO test_bank_speaking_items(created_by_teacher_id,title,instruction,prompt_text,status) VALUES (3,'Test: Propose a solution — A delayed shipment','Imagine you receive a voicemail from a supplier saying that an important shipment will arrive one week late. Explain the problem and recommend a solution to your manager. You have 60 seconds.','Describe the problem, say how it affects your project or customers, and suggest at least two ways to solve it.','ACTIVE');
